# The pass that plays lost-click-probe.feature: windows that make a click lose itself, and the symptom asserted (the page does not
# open), with the keyed click that makes it play in French too. The deliberately failing copy that shows the report's text is
# Upstream/tests/lost-click-probe.feature and runs with the same map.
#
#   scripts/Run-PickleWsl.ps1 -Mod PickleTools -DepMap wsl-deps.lostclickprobe.map -Filter lost-click-probe
#
# `path:` names a folder of this repository (relative to its root); the folder's own About.xml packageId must match.
nelim.pickletools.keyedclick       path:PickleTools/KeyedClick/Mod
nelim.pickletools.lostclickprobe   path:PickleTools/Upstream/tests/lost-click-probe/Mod
